 291	    private function enfStepper(EnfAccion $accion): array
 292	    {
 293	        $proceso = EnfRevision::where('enf_accion_id', $accion->id)
 294	            ->orderByDesc('id')
 295	            ->value('proceso');
 296	
 297	        if (! $proceso) {
 298	            return [];
 299	        }
 300	
 301	        $actualMarcado = false;
 302	
 303	        return EnfRevision::where('enf_accion_id', $accion->id)
 304	            ->where('proceso', $proceso)
 305	            ->orderByDesc('revision_ciclo')
 306	            ->orderByDesc('id')
 307	            ->get()
 308	            ->unique('flujo_aprobacion_etapa_id')
 309	            ->sortBy('orden')
 310	            ->values()
 311	            ->map(function (EnfRevision $revision) use (&$actualMarcado): array {
 312	                $estado = 'pendiente';
 313	
 314	                if ($revision->estado === 'APROBADO') {
 315	                    $estado = 'aprobado';
 316	                } elseif ($revision->estado === 'SUBSANACION') {
 317	                    $estado = 'rechazado';
 318	                } elseif (! $actualMarcado) {
 319	                    $estado = 'actual';
 320	                    $actualMarcado = true;
 321	                }
 322	
 323	                return ['nombre' => $revision->etapa_nombre, 'estado' => $estado];
 324	            })
 325	            ->all();
 326	    }
